import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="SÍNCOPE"; N=7
note=lambda t: f'<div style="font-size:34px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:20px">'+"".join(x)+'</div>'
P=[
page(1,N,T,big("SÍNCOPE",200,nowrap=True)+big(f'LA MAYORÍA SE VA A CASA. <span style="color:{R}">EL RETO ES ENCONTRAR AL QUE NO</span>',100)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Qué hacer a todos, qué señales de riesgo buscar y adónde va cada paciente. Con ficha final.</div>',cover=True),
page(2,N,T,kicker("¿ES UN SÍNCOPE?")+big("PÉRDIDA BREVE DE CONSCIENCIA",104)+rows(line("Por hipoperfusión cerebral"),line("Inicio rápido, duración corta"),line("Recuperación espontánea y completa",True))+note("Si no cumple los tres, piensa en otra cosa: crisis epiléptica, traumatismo craneal, hipoglucemia o intoxicación.")),
page(3,N,T,kicker("A TODOS")+big("TRES COSAS",170,R,True)+rows(num(1,"Anamnesis detallada del episodio"),num(2,"PA tumbado y de pie"),num(3,"ECG de 12 derivaciones"))+note("Ortostatismo: caída de la PAS ≥ 20 mmHg o de la PAD ≥ 10 mmHg, o PAS &lt; 90 mmHg. Analítica e imagen según la sospecha, no de rutina; troponina solo si sospechas isquemia.")),
page(4,N,T,kicker("ALTO RIESGO · CLÍNICA")+big("BUSCA ESTO",170,nowrap=True)+rows(line("Durante el esfuerzo o en decúbito",True),line("Palpitaciones bruscas justo antes"),line("Dolor torácico, disnea, dolor abdominal o cefalea nuevos"),line("Cardiopatía estructural o coronaria grave",True),line("PAS &lt; 90 sin causa, sangrado digestivo, FC &lt; 40 o soplo sistólico nuevo"))),
page(5,N,T,kicker("ALTO RIESGO · ECG")+big("EL ECG MANDA",160,R,True)+rows(line("Isquemia aguda"),line("BAV de 2.º grado Mobitz II o de 3.<sup>er</sup> grado",True),line("Bradicardia &lt; 40 lpm o pausas &gt; 3 s despierto"),line("TV, Brugada tipo 1 o QTc &gt; 460 ms repetido",True),line("Bloqueo de rama, ondas Q o fallo de marcapasos o DAI"))),
page(6,N,T,kicker("¿Y AHORA QUÉ?")+big("DESTINO",200,nowrap=True)+rows(row("Bajo riesgo","Alta desde Urgencias"),row("Ni alto ni bajo","Observación en Urgencias o unidad de síncope"),f'<div style="border-top:4px solid {K};padding-top:22px;display:flex;justify-content:space-between;gap:32px;font-size:40px;color:{R}"><div style="font-weight:800">Alto riesgo</div><div style="font-weight:800;text-align:right">Unidad de síncope precoz o ingreso</div></div>')+note("Bajo riesgo: pródromo reflejo típico, desencadenante claro, episodios previos iguales, sin cardiopatía, exploración y ECG normales. Las escalas no superan al juicio clínico: no las uses solas.")),
page(7,N,T,ficha_body("SÍNCOPE","Adulto",[("A TODOS","Anamnesis, PA tumbado y de pie, ECG de 12 derivaciones"),("ORTOSTATISMO","Caída PAS ≥ 20 o PAD ≥ 10 mmHg, o PAS &lt; 90 mmHg"),("CLÍNICA","Esfuerzo o decúbito, palpitaciones previas, dolor torácico, cardiopatía, PAS &lt; 90"),("ECG","Isquemia, Mobitz II o BAV 3.º, FC &lt; 40, pausas &gt; 3 s, TV, Brugada 1, QTc &gt; 460",True),("BAJO RIESGO","Pródromo reflejo, sin cardiopatía, ECG normal: alta"),("ALTO RIESGO","Unidad de síncope precoz o ingreso",True)],"Brignole M, et al. Guía ESC 2018 sobre el diagnóstico y el tratamiento del síncope. Rev Esp Cardiol 2018;71(10):837.e1-e92",size=136,fs=30),ficha="10"),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","sincope")
